package com.enterpriseflow.entity;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="activity_logs") public class ActivityLog {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) private User actor; private String action; private String entityType; private UUID entityId; private String summary; private Instant createdAt; protected ActivityLog(){} public ActivityLog(User a,String ac,String type,UUID eid,String s){actor=a;action=ac;entityType=type;entityId=eid;summary=s;}@PrePersist void on(){createdAt=Instant.now();}public UUID getId(){return id;}public String getAction(){return action;}public String getEntityType(){return entityType;}public String getSummary(){return summary;}public Instant getCreatedAt(){return createdAt;}public User getActor(){return actor;}}
